package pl.zagranietyper;import com.fasterxml.jackson.databind.ObjectMapper;import pl.zagranietyper.config.*;import pl.zagranietyper.fixture.ApiFootballClient;import pl.zagranietyper.model.FootballFixturePlayerStatisticsSnapshot;import pl.zagranietyper.repository.*;import pl.zagranietyper.service.*;import java.util.*;
/** Resumable player-statistics validation/backfill; never writes settlement state. */
public final class FootballFixturePlayerStatisticsBackfillMain {private FootballFixturePlayerStatisticsBackfillMain(){}public static void main(String[]args){Options o=parse(args);var mapper=new ObjectMapper();var db=new Database(AppConfig.fromEnvironment());db.initializeSchema();var repo=new FootballFixturePlayerStatisticsRepository(db,mapper);var targets=new FootballFixturePlayerStatisticsTargetSelector(db).findTargets();var service=new FootballFixturePlayerStatisticsIngestionService(new ApiFootballClient(ApiFootballConfig.fromEnvironment(),mapper),repo,new FootballFixturePlayerStatisticsNormalizer());System.out.println("targetFixtures="+targets.size());if(o.validate>0){for(long id:targets.stream().limit(o.validate).toList()){var s=service.inspect(id);System.out.println("VALIDATE fixture="+id+" status="+s.status()+" players="+s.players().size());s.players().stream().filter(p->p.goals()!=null&&p.goals()>0||p.assists()!=null&&p.assists()>0||p.saves()!=null&&p.saves()>0||p.yellowCards()!=null&&p.yellowCards()>0||Boolean.TRUE.equals(p.substitute())).limit(12).forEach(p->System.out.println(" team="+p.teamId()+" player="+p.playerId()+"/"+p.playerName()+" min="+p.minutes()+" sub="+p.substitute()+" shots="+p.shotsTotal()+"/"+p.shotsOnTarget()+" goals="+p.goals()+" assists="+p.assists()+" saves="+p.saves()+" cards="+p.yellowCards()+"/"+p.redCards()));}return;}if(o.run)for(long id:targets){if(repo.loadStatus(id).orElse(null)==FootballFixturePlayerStatisticsSnapshot.FetchStatus.COMPLETE)continue;var s=service.ingest(id);System.out.println("fixture="+id+" status="+s.status()+" players="+s.players().size());}audit(targets,repo);}static void audit(List<Long>ids,FootballFixturePlayerStatisticsRepository repo){EnumMap<FootballFixturePlayerStatisticsSnapshot.FetchStatus,Integer>c=new EnumMap<>(FootballFixturePlayerStatisticsSnapshot.FetchStatus.class);for(var s:FootballFixturePlayerStatisticsSnapshot.FetchStatus.values())c.put(s,0);int missing=0,players=0,appear=0;for(long id:ids){var st=repo.loadStatus(id);if(st.isEmpty()){missing++;continue;}c.merge(st.get(),1,Integer::sum);for(var p:repo.loadPlayers(id)){players++;if(p.appearanceConfirmed())appear++;}}System.out.println("AUDIT targetFixtures="+ids.size()+" missing="+missing+" statuses="+c);System.out.println("playersStored="+players+" appearanceConfirmed="+appear);}static Options parse(String[]a){boolean run=false;int validate=0;for(String x:a==null?new String[0]:a){if(x.equals("--run-all"))run=true;else if(x.startsWith("--validate="))validate=Integer.parseInt(x.substring(11));else throw new IllegalArgumentException("Usage: [--validate=N | --run-all]");}if(run&&validate>0)throw new IllegalArgumentException("choose validation or run");return new Options(run,validate);}record Options(boolean run,int validate){}}
